class GameAutomation:
    def __init__(self, game_client):
        self.game = game_client
        self.current_money = 1262
        self.level_id = 1
        self.level_complete = False
        self.start_time = time.time()
        self.max_time = 24 * 3600  # 24 hours
        self.upgrades_bought = set()
        self.items_collected = []

    def get_state(self):
        try:
            state = self.game.get_state()
            self.current_money = state.get('money', self.current_money)
            self.level_complete = state.get('level_complete', False)
            return state
        except Exception as e:
            logger.error(f"Error getting state: {e}")
            return None

    def explore(self):
        try:
            result = self.game.explore()
            logger.info(f"Explored: {result}")
            return True
        except Exception as e:
            logger.error(f"Error exploring: {e}")
            return False

    def collect(self):
        try:
            result = self.game.collect()
            if result:
                self.items_collected.append(result)
                logger.info(f"Collected: {result}")
            return result
        except Exception as e:
            logger.error(f"Error collecting: {e}")
            return None

    def get_upgrades(self):
        try:
            return self.game.get_upgrades()
        except Exception as e:
            logger.error(f"Error getting upgrades: {e}")
            return []

    def apply_upgrades(self):
        upgrades = self.get_upgrades()
        for upgrade in upgrades:
            if upgrade['id'] not in self.upgrades_bought:
                try:
                    cost = upgrade['cost']
                    if self.current_money >= cost:
                        self.game.buy_upgrade(upgrade['id'])
                        self.upgrades_bought.add(upgrade['id'])
                        self.current_money -= cost
                        logger.info(f"Bought upgrade: {upgrade['id']}")
                except Exception as e:
                    logger.error(f"Error buying upgrade: {e}")

    def sell_items(self):
        for item in self.items_collected:
            try:
                price = self.game.sell(item)
                self.current_money += price
                logger.info(f"Sold {item} for {price}")
            except Exception as e:
                logger.error(f"Error selling {item}: {e}")
        self.items_collected = []

    def optimize_actions(self):
        # Simulate optimization logic
        time.sleep(0.1)  # Small delay to prevent spam

    def run(self):
        logger.info("Starting automation...")
        while not self.level_complete and (time.time() - self.start_time) < self.max_time:
            try:
                state = self.get_state()
                if not state:
                    continue

                # Explore
                self.explore()

                # Collect
                self.collect()

                # Apply upgrades
                self.apply_upgrades()

                # Sell items
                self.sell_items()

                # Optimize
                self.optimize_actions()

            except Exception as e:
                logger.error(f"Unexpected error in loop: {e}")
                time.sleep(1)  # Backoff on error

        logger.info(f"Automation finished. Final money: {self.current_money}")
        return self.current_money

